def verify_isbn(isbn: str) -> str:
    # Remove hyphens to get the digits
    digits = isbn.replace('-', '')

    # Validate length: should be 10 characters
    if len(digits) != 10:
        raise ValueError("ISBN must be 10 characters long (excluding hyphens)")

    # Validate format: first 9 must be digits, last can be digit or 'X'
    for i in range(9):
        if not digits[i].isdigit():
            raise ValueError(f"Position {i} must be a digit")
    if not (digits[9].isdigit() or digits[9] == 'X'):
        raise ValueError("Last character must be a digit or 'X'")

    # Calculate checksum
    total = 0
    for i in range(9):
        total += int(digits[i]) * (10 - i)

    # The checksum digit should make the total divisible by 11
    # So the required checksum value is (11 - total % 11) % 11
    required_checksum = (11 - total % 11) % 11

    # Check if the last digit matches
    if digits[9] == 'X':
        actual_checksum = 10
    else:
        actual_checksum = int(digits[9])

    if actual_checksum == required_checksum:
        return "Right"
    else:
        # Correct the last digit
        if required_checksum == 10:
            corrected_last = 'X'
        else:
            corrected_last = str(required_checksum)

        # Reconstruct the ISBN with the same hyphen pattern
        # The format is 'x-xxx-xxxxx-x'
        # We need to preserve the hyphen positions
        # Let's find the hyphen positions in the original
        hyphen_positions = [i for i, c in enumerate(isbn) if c == '-']

        # Build the corrected ISBN
        corrected_digits = digits[:9] + corrected_last
        result = []
        digit_idx = 0
        for i, c in enumerate(isbn):
            if c == '-':
                result.append('-')
            else:
                result.append(corrected_digits[digit_idx])
                digit_idx += 1

        return ''.join(result)
