def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1")

    # Check for factor 2
    if n % 2 == 0:
        return n // 2

    # Check odd factors from 3 up to sqrt(n)
    i = 3
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 2

    # If no factor found, n is prime
    return n
